async fn handle_new_email_safe(db: &Database, email: Email) {
    // Perform both writes inside a single atomic transaction
    let mut tx = db.begin().await.unwrap();
    tx.execute("INSERT INTO emails (id, body) VALUES ($1, $2)", &[&email.id, &email.body]).await.unwrap();
    tx.execute("UPDATE mailboxes SET unread = unread + 1 WHERE user_id = $1", &[&email.user_id]).await.unwrap();
    tx.commit().await.unwrap();
}
